-- Migration 0017 : premier lot de documents identifiés manquants après
-- analyse des 87 vrais documents d'audit de Nora (cf. Phase 5 du journal).
-- Priorité haute : les indicateurs 2 et 17 n'avaient jusqu'ici AUCUN document
-- généré. On ajoute aussi le formulaire de réclamation (le formulaire
-- lui-même, pas seulement la procédure), son accusé de réception, le
-- questionnaire de recueil des besoins et le questionnaire de satisfaction,
-- dont la structure réelle a été extraite des vrais formulaires de Nora.
--
-- Réutilisation délibérée de l'existant plutôt que de nouveaux content_block
-- types : la fiche moyens pédagogiques réutilise le type 'method' (déjà
-- alimenté par domaine, cf. migrations 0005/0011) via content_block_scope
-- 'training', et le questionnaire de besoins réutilise 'need_example' de la
-- même façon — aucune nouvelle banque de contenu à créer pour ce lot.

insert into document_templates (id, label, category_scope, applicable_when, linked_indicator_numbers, folder_group, sort_order, is_active) values
('questionnaire_besoins', 'Questionnaire de recueil des besoins', 'all', '{}'::jsonb, ARRAY[4], '03_Avant_formation', 12, true),
('fiche_moyens_pedagogiques', 'Fiche des moyens pédagogiques, techniques et humains', 'all', '{}'::jsonb, ARRAY[17], '06_Procedures', 15, true),
('resultats_indicateurs_qualite', 'Nos résultats — indicateurs de résultats', 'all', '{}'::jsonb, ARRAY[2], '08_Amelioration', 105, true),
('formulaire_reclamation', 'Formulaire de réclamation', 'all', '{}'::jsonb, ARRAY[31], '08_Amelioration', 115, true),
('accuse_reception_reclamation', 'Accusé de réception d''une réclamation', 'all', '{}'::jsonb, ARRAY[31], '08_Amelioration', 116, true),
('questionnaire_satisfaction', 'Questionnaire de satisfaction', 'all', '{}'::jsonb, ARRAY[30], '05_Apres_formation', 20, true);

