-- ---------- QUESTIONNAIRE DE RECUEIL DES BESOINS (indicateur 4) ----------
('questionnaire_besoins', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — Questionnaire de recueil des besoins</p><p>Formation envisagée : <strong>{{training_name}}</strong></p><p>Nom et prénom du bénéficiaire : …………………………………… &nbsp; Entreprise (le cas échéant) : ……………………………………</p><p>Date : …………………………………</p>', null, 'global'),
('questionnaire_besoins', 'situation', 'Situation actuelle', 2, 'rich_text', '<p>Poste occupé / statut actuel : ……………………………………</p><p>Expérience dans le domaine de la formation : ☐ Aucune &nbsp; ☐ Débutant &nbsp; ☐ Intermédiaire &nbsp; ☐ Avancé</p><p>Difficultés rencontrées actuellement en lien avec ce domaine : ……………………………………………………………………</p>', null, 'global'),
('questionnaire_besoins', 'objectifs_beneficiaire', 'Vos objectifs', 3, 'rich_text', '<p>Qu''attendez-vous personnellement de cette formation ? ……………………………………………………………………</p><p>Quelles compétences souhaitez-vous acquérir ou renforcer en priorité ? ……………………………………………………………………</p>', null, 'global'),
('questionnaire_besoins', 'objectifs_entreprise', 'Objectifs de l''entreprise / du financeur (si applicable)', 4, 'rich_text', '<p>Contexte professionnel ayant motivé cette formation : ……………………………………………………………………</p><p>Résultats attendus par l''employeur ou le financeur : ……………………………………………………………………</p>', null, 'global'),
('questionnaire_besoins', 'besoins_specifiques', 'Exemples de besoins fréquents dans ce domaine', 5, 'content_block_list', null, 'need_example', 'training'),
('questionnaire_besoins', 'preferences_pedagogiques', 'Préférences pédagogiques', 6, 'rich_text', '<p>Modalité préférée : ☐ Présentiel &nbsp; ☐ Distanciel &nbsp; ☐ Hybride</p><p>Rythme souhaité : ☐ Journées complètes &nbsp; ☐ Demi-journées &nbsp; ☐ Sur plusieurs semaines</p><p>Contraintes d''emploi du temps à prendre en compte : ……………………………………………………………………</p>', null, 'global'),
('questionnaire_besoins', 'accessibilite', 'Accessibilité', 7, 'rich_text', '<p>Êtes-vous en situation de handicap ou avez-vous un besoin d''aménagement particulier ? ☐ Oui &nbsp; ☐ Non</p><p>Si oui, merci de contacter {{disability_referent_name}} ({{disability_referent_email}}) pour étudier les aménagements possibles.</p>', null, 'global'),
('questionnaire_besoins', 'validation', 'Validation', 8, 'rich_text', '<p>Ce questionnaire nous permet d''adapter le programme et les modalités de la formation à votre situation. Vos réponses restent confidentielles.</p><p>Date : …………………………………… &nbsp; Signature : ……………………………………</p>', null, 'global'),

-- ---------- FICHE MOYENS PÉDAGOGIQUES, TECHNIQUES ET HUMAINS (indicateur 17) ----------
('fiche_moyens_pedagogiques', 'header', 'En-tête', 1, 'rich_text', '<p>Organisme : {{company_name}}<br/>Objet : Fiche des moyens pédagogiques, techniques et humains mobilisés<br/>Version : {{procedure_version}}</p>', null, 'global'),
('fiche_moyens_pedagogiques', 'moyens_humains', 'Moyens humains', 2, 'rich_text', '<table><thead><tr><th>Fonction</th><th>Nom</th><th>Rôle dans la prestation</th></tr></thead><tbody><tr><td>Direction / référent pédagogique</td><td>{{pedagogical_referent_name}}</td><td>Conception et supervision pédagogique</td></tr><tr><td>Référent qualité</td><td>{{quality_referent_name}}</td><td>Suivi qualité et amélioration continue</td></tr><tr><td>Référent handicap</td><td>{{disability_referent_name}}</td><td>Accueil et accompagnement des publics en situation de handicap</td></tr><tr><td>Formateur·rice (intervenant externe, le cas échéant)</td><td>{{external_trainer_name}}</td><td>{{external_trainer_discipline}}</td></tr></tbody></table><p>{{sole_practitioner_note}}</p>', null, 'global'),
('fiche_moyens_pedagogiques', 'moyens_techniques', 'Moyens techniques', 3, 'rich_text', '<ul><li>Locaux et équipements adaptés à la modalité {{training_modality}} de la formation.</li><li>Pour les sessions à distance : plateforme de visioconférence et outils numériques fournis par {{technical_provider_name}} ({{technical_provider_company}}).</li><li>Supports de formation transmis aux bénéficiaires (présentations, exercices, ressources complémentaires).</li><li>Feuille d''émargement et outils de suivi de l''assiduité.</li></ul>', null, 'global'),
('fiche_moyens_pedagogiques', 'moyens_pedagogiques', 'Méthodes pédagogiques mobilisées pour cette formation', 4, 'content_block_list', null, 'method', 'training'),
