-- ---------- NOS RÉSULTATS (indicateur 2) ----------
('resultats_indicateurs_qualite', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — Indicateurs de résultats</p><p>Document mis à disposition du public conformément à l''indicateur 2 du référentiel national qualité (diffusion d''indicateurs de résultats adaptés à la nature des prestations).</p>', null, 'global'),
('resultats_indicateurs_qualite', 'tableau_resultats', 'Nos indicateurs', 2, 'rich_text', '<table><thead><tr><th>Indicateur</th><th>Résultat</th><th>Objectif visé</th></tr></thead><tbody><tr><td>Taux de satisfaction des stagiaires</td><td>{{computed_learner_satisfaction}}</td><td>{{satisfaction_rate_target}}</td></tr><tr><td>Taux de satisfaction des formateurs</td><td>{{computed_trainer_satisfaction}}</td><td>{{trainer_satisfaction_rate_target}}</td></tr><tr><td>Taux de satisfaction des entreprises / financeurs</td><td>{{computed_partner_satisfaction}}</td><td>{{partner_satisfaction_rate_target}}</td></tr><tr><td>Taux de réussite</td><td>{{computed_success_rate}}</td><td>{{success_rate_target}}</td></tr><tr><td>Taux d''insertion à 6 mois</td><td>{{computed_insertion_rate}}</td><td>{{insertion_rate_target_6months}}</td></tr><tr><td>Taux de réclamations résolues</td><td>{{computed_complaints_resolved_ratio}}</td><td>100 %</td></tr></tbody></table>', null, 'global'),
('resultats_indicateurs_qualite', 'methodologie', 'Méthodologie', 3, 'rich_text', '<p>Ces indicateurs sont calculés à partir des questionnaires de satisfaction, du registre des réclamations et du suivi des sessions réalisées. Ils sont mis à jour {{watch_review_frequency}} par {{quality_referent_name}}.</p>', null, 'global'),
('resultats_indicateurs_qualite', 'publication', 'Publication', 4, 'rich_text', '<p>Ces résultats sont consultables sur {{company_website}} et communiqués sur demande à toute personne intéressée, conformément à l''obligation d''information du public (indicateurs 1 et 2 du référentiel national qualité).</p>', null, 'global'),

-- ---------- FORMULAIRE DE RÉCLAMATION (indicateur 31) ----------
('formulaire_reclamation', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — Formulaire de réclamation</p><p>Ce formulaire permet à tout stagiaire, entreprise, financeur, formateur ou partenaire de signaler un dysfonctionnement ou d''exprimer une insatisfaction.</p>', null, 'global'),
('formulaire_reclamation', 'profil', 'Votre profil', 2, 'rich_text', '<p>☐ Stagiaire &nbsp; ☐ Entreprise &nbsp; ☐ Financeur &nbsp; ☐ Formateur &nbsp; ☐ Partenaire &nbsp; ☐ Autre : ……………………</p><p>Nom et prénom : …………………………………… &nbsp; Email : …………………………………… &nbsp; Téléphone : ……………………………………</p><p>Formation / session concernée : …………………………………… &nbsp; Date des faits : ……………………………………</p>', null, 'global'),
('formulaire_reclamation', 'description', 'Votre réclamation', 3, 'rich_text', '<p>Objet de la réclamation : ……………………………………………………………………</p><p>Description détaillée : ……………………………………………………………………</p><p>……………………………………………………………………</p><p>……………………………………………………………………</p><p>Mesures déjà tentées pour résoudre la situation (le cas échéant) : ……………………………………………………………………</p><p>Niveau d''urgence perçu : ☐ Faible &nbsp; ☐ Moyen &nbsp; ☐ Élevé</p>', null, 'global'),
('formulaire_reclamation', 'rgpd_delais', 'Consentement et délais', 4, 'rich_text', '<p>☐ J''accepte que les informations transmises soient utilisées par {{company_name}} dans le seul cadre du traitement de cette réclamation, conformément au RGPD ({{dpo_contact_email}}).</p><p>Un accusé de réception vous sera adressé sous {{complaint_ack_delay}}. Une réponse motivée vous sera communiquée sous {{complaint_response_delay}}.</p><p>Date : …………………………………… &nbsp; Signature : ……………………………………</p>', null, 'global'),

-- ---------- ACCUSÉ DE RÉCEPTION D'UNE RÉCLAMATION (indicateur 31) ----------
('accuse_reception_reclamation', 'content', 'Accusé de réception', 1, 'rich_text', '<p>{{company_name}} — {{address}}</p><p>{{organization_city}}, le {{generated_date}}</p><p><strong>Objet : Accusé de réception de votre réclamation</strong></p><p>Madame, Monsieur,</p><p>Nous accusons réception de votre réclamation transmise via notre formulaire de réclamation.</p><p>Conformément à notre procédure qualité, nous nous engageons à vous apporter une réponse motivée sous {{complaint_response_delay}} à compter de ce jour.</p><p>Votre dossier est traité par {{quality_referent_name}} ({{complaints_email}}).</p><p>En cas de désaccord persistant à l''issue de notre réponse, vous disposez d''un droit à saisir un médiateur de la consommation.</p><p>Nous vous prions d''agréer, Madame, Monsieur, l''expression de nos salutations distinguées.</p><p>{{director_name}}<br/>{{company_name}}</p>', null, 'global'),

